package com.careerpilot.modules.assessment.entity;
import com.careerpilot.modules.auth.entity.User;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="assessment_attempts") @Getter @Setter @NoArgsConstructor
public class AssessmentAttempt{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="assessment_id")private Assessment assessment;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AttemptStatus status;@Column(name="started_at",nullable=false)private Instant startedAt;@Column(name="submitted_at")private Instant submittedAt;@Column(name="score_percentage")private Integer scorePercentage;@Column(name="correct_answers",nullable=false)private int correctAnswers;@Column(name="incorrect_answers",nullable=false)private int incorrectAnswers;@Column(nullable=false)private int unanswered;@Column(name="total_questions",nullable=false)private int totalQuestions;@Column(name="duration_seconds")private Integer durationSeconds;@Column(name="created_at",nullable=false)private Instant createdAt;@OneToMany(mappedBy="attempt",cascade=CascadeType.ALL,orphanRemoval=true)private List<AssessmentAnswer>answers=new ArrayList<>();@OneToMany(mappedBy="attempt",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("questionOrder")private List<AssessmentAttemptQuestion>selectedQuestions=new ArrayList<>();@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(startedAt==null)startedAt=Instant.now();if(createdAt==null)createdAt=startedAt;}}
